  try{GUIDE.forEach(function(g){(g.items||[]).forEach(function(it){var q=it[0];if(q&&q[0])kbAdd(d,q[0]+' '+(g.t&&g.t[0]||''),q[0],'دليل التطبيق',.8)})})}catch(e){}
